from fastapi import FastAPI
import asyncio

def s_start():
    print("SYNC START", flush=True)

def s_shutdown():
    print("SYNC SHUTDOWN", flush=True)

app = FastAPI(on_startup=[s_start], on_shutdown=[s_shutdown])

@app.get("/health")
async def health():
    return {"ok": True}

async def test_lifespan():
    from fastapi.testclient import TestClient
    with TestClient(app):
        pass

if __name__ == "__main__":
    asyncio.run(test_lifespan())
